#include "config.h"
#include "json.h"
namespace rc { namespace { std::filesystem::path AppDir(){wchar_t b[MAX_PATH];DWORD n=GetEnvironmentVariableW(L"LOCALAPPDATA",b,MAX_PATH);return std::filesystem::path(std::wstring(b,n))/L"RoboconCadManager";} }
ConfigStore::ConfigStore():root_(AppDir()){} bool ConfigStore::Load(std::wstring& error){repositories_.clear();std::ifstream f(root_/L"settings.json",std::ios::binary);if(!f)return true;std::string raw((std::istreambuf_iterator<char>(f)),{});auto doc=Json::Parse(Wide(raw),&error);if(!doc)return false;auto a=doc->Find(L"repositories");if(!a||a->type!=Json::Type::Array)return true;for(auto&v:a->array){if(v.type!=Json::Type::Object)continue;Repository r; if(auto x=v.Find(L"name"))r.name=x->StringOr();if(auto x=v.Find(L"remote"))r.remote=x->StringOr();if(auto x=v.Find(L"folder"))r.folder=x->StringOr();if(auto x=v.Find(L"userName"))r.userName=x->StringOr();if(auto x=v.Find(L"userEmail"))r.userEmail=x->StringOr();if(auto x=v.Find(L"lfsLockEnabled"))r.lfsLockEnabled=x->BoolOr();if(!r.name.empty())repositories_.push_back(std::move(r));}return true;}
bool ConfigStore::Save(std::wstring& error)const{std::error_code ec;std::filesystem::create_directories(root_,ec);if(ec){error=L"設定フォルダを作成できません: "+Wide(ec.message());return false;}Json root;root.type=Json::Type::Object;Json a;a.type=Json::Type::Array;for(auto&r:repositories_){Json o;o.type=Json::Type::Object;for(auto [k,v]:std::initializer_list<std::pair<std::wstring,std::wstring>>{{L"name",r.name},{L"remote",r.remote},{L"folder",r.folder},{L"userName",r.userName},{L"userEmail",r.userEmail}}){Json x;x.type=Json::Type::String;x.string=v;o.object[k]=std::move(x);}Json locking;locking.type=Json::Type::Bool;locking.boolean=r.lfsLockEnabled;o.object[L"lfsLockEnabled"]=std::move(locking);a.array.push_back(std::move(o));}root.object[L"repositories"]=std::move(a);std::ofstream f(root_/L"settings.json",std::ios::binary|std::ios::trunc);if(!f){error=L"設定ファイルを書き込めません";return false;}f<<Utf8(root.Dump());return (bool)f;}
void ConfigStore::Upsert(Repository r){auto i=std::find_if(repositories_.begin(),repositories_.end(),[&](const Repository& v){return v.name==r.name;});if(i==repositories_.end())repositories_.push_back(std::move(r));else *i=std::move(r);}
std::optional<Policy>ReadPolicy(const std::filesystem::path&repo,std::wstring&error){std::ifstream f(repo/L"00_admin"/L"robocon-policy.json",std::ios::binary);if(!f){error=L"00_admin/robocon-policy.json が見つかりません";return{};}std::string raw((std::istreambuf_iterator<char>(f)),{});auto j=Json::Parse(Wide(raw),&error);if(!j||j->type!=Json::Type::Object)return{};Policy p;if(auto x=j->Find(L"version"))p.version=(int)x->number;if(auto x=j->Find(L"mainBranch"))p.mainBranch=x->StringOr(L"main");if(auto x=j->Find(L"backupGuide"))p.backupGuide=x->StringOr();if(auto x=j->Find(L"leaders");x&&x->type==Json::Type::Array)for(auto&v:x->array)if(v.type==Json::Type::String)p.leaders.push_back(v.string);return p;}}
